#!/usr/bin/env python3
"""Assemble the 12 verdicts from preserved browser observations."""
import collections,datetime,hashlib,json,re,subprocess
from pathlib import Path
R=Path(__file__).resolve().parent
P=R.parent
ids=['QA-026','QA-028','QA-029','QA-037','QA-038','QA-039','QA-050','QA-057','QA-095','QA-096','QA-098','QA-121']
read=lambda f:json.loads((R/f).read_text())
inventory=json.loads((P/'package-inventory.json').read_text())
baseline=subprocess.check_output(['git','-C','/home/daksh/src/triangulator-qa-react-full-c16a553','show','c16a55383c4bc6a219c270aa4f7cf9b55c97e45a:docs/qa/test-cases.md'],text=True)
definitions={}
for case in ids:
 m=re.search(r'^## '+case+r':.*?(?=^## |\Z)',baseline,re.M|re.S)
 assert m,case
 definitions[case]={'revision':inventory['cases'][case]['revision'],'definition':m.group().strip()}
(R/'case-definitions-c16.json').write_text(json.dumps(definitions,indent=2))
final_browser=read('final-browser-observations.json')['observations']
proc=next(x for x in final_browser if x['id']=='QA-028')
assert proc['preconditions']=={'exe_deleted':True,'command_truncated':True}
assert '(deleted)' in proc['facts'] and ' …' in proc['facts']
rate=next(x for x in final_browser if x['id']=='QA-095')
assert rate['threads']>=20 and rate['notAvailable'] and rate['frozen']
closing=read('closing-observations.json')['scenarios']
by_name={x['name']:x for x in closing}
for name in ['settle-sampled-thresholds','explicit-range-counts','interrupted-period-retry','help-controls-gaps','empty-recording-installation','disabled-memory-after-restart']:
 assert by_name[name]['status']=='PASSED',name
scope=by_name['whole-host-scope-summary'];assert scope['chartChanged'] and not scope['summaryChanged']
mem=read('memory-controls-observations.json')['observations'];assert mem[0]['keptSpan'] and mem[0]['expanded']
assert not mem[1]['waiting']['mapVisible'] and mem[1]['after']['fold'] and mem[1]['after']['membersOpen']==''
assert 'Collecting' in mem[1]['after']['charts'] and not mem[1]['after']['cards']
main=read('observations.json')['observations']
holds=next(x['result'] for x in main if isinstance(x.get('result'),list) and len(x['result'])==3 and x['result'][0].get('sel')=='#mosaic .cell')
assert all(x['frozen'] and x['cardFrozen'] and x['release'] for x in holds)
resource_holds=next(x['result'] for x in main if isinstance(x.get('result'),list) and len(x['result'])==3 and x['result'][0].get('sel')=='#pressure-rows td:nth-child(2)')
assert all(x['frozen'] and x['cardFrozen'] and x['release'] for x in resource_holds)
native=read('native-complete-observations.json')['scenarios'];bar=next(x for x in native if x['name']=='bar-grid-click-escape-margin')
assert bar['hoverCard']==[] and bar['barFrozen'] is False
reset=next(x for x in native if x['name']=='socket-and-map-replacement');assert reset['status']=='PASSED'
last_native=read('last-native-observations.json')['observations'];grid=next(x for x in last_native if x['id']=='QA-098')
assert grid['frozen'] and grid['before']==grid['inCard'] and grid['escape1']==grid['escape2']==0
resources=read('resources-last-observations.json')['observations'];assert resources[0]['changed']
rr=resources[1];assert all(rr[k]['cards']==[] for k in ['h1','h6','host']) and all(rr[k] for k in ['before','before6','beforeScope'])
cases=[]
def add(id,status,observation,evidence,verified,excluded=None):
 cases.append({'id':id,'revision':definitions[id]['revision'],'status':status,'tested_package_version':'dev-c16a553','observations':observation,'verified_expectations':verified,'evidence':evidence,'unverified_or_excluded_expectations':excluded or []})
add('QA-026','PASSED','Own browser watched busy for 317 s, 20:43:44–20:49:01 UTC. Final PID 280116 stayed inspectable after exit, reload, new tab and replacement. Show live selected PID 299407. A never-running fixture showed absence.', ['observations.json'],['CPU/RSS/VmSize trends retained where this tab had them','History request end=1793134141 equals final sample; 106 summaries end before exit','Recording navigation remains usable','Reload and new tab retain the final process; a new tab explains missing local trends','Restart preserves old evidence until Show live','Never-running target has no final view'])
add('QA-028','PASSED','Native identity matches /proc and host ps with container PID mapping. Affinity 2–3, permission reasons, deleted executable, ellipsis-marked long arguments, target changes, replay and final runtimes were observed.', ['finish-observations.json','native-observations.json','final-browser-observations.json','deleted-process-ready.json'],['Command/executable/cwd/UID/GID/parent/affinity match native evidence','Restricted executable/cwd show readable-only-by-owner reasons','Deleted executable is marked (deleted)','A command with 10000 extra argument bytes is visibly shortened and marked with an ellipsis; the API command_truncated flag is true','New target does not show old identity','Recorded runtime is 8 min for 500 s; final runtime is 61 min for 3660 s and stays fixed'])
add('QA-029','PASSED','RSS grew from 55.1 MiB to 131.2 MiB during the owned browser observation. Summary windows, help, recorded mode, Live and disabled memory sampling across a controlled process replacement were checked.', ['observations.json','native-observations.json','finish-observations.json','closing-observations.json'],['Growth observed for more than two minutes','1/5/15-minute Summary windows share CPU/RSS/VmSize time bounds','Summary and Memory values use binary units and agree with the same sampled values','Load, memory-use, RSS and VmSize help opened','Recorded mode hides live-trend containers; Live restores them','Disabled VmSize names memory_interval_s=0 and has no visible chart after restart'])
add('QA-037','FAILED','Add rule, Save and Reset to config file have no hover help. Label/wrapper keyboard help works. Draft, read-only, endpoint, connection failure, late read/write, final and sampled-threshold checks passed.', ['fixture-driver-observations.json','fixture-observations.json','closing-observations.json','controlled-observations.json','qa-037-continuation-failure.png'],['Section/column labels open help by pointer and keyboard','Control wrappers open keyboard help','Recorded editor is hidden/read-only; draft survives Live','Missing watches names /api/watches and collector.toml','Actual test-collector outage preserves the draft and reports Failed to fetch','Pending read does not replace a draft','Sent write settles current configuration without changing selected recording; no recorded watch reads occur','Final editor remains available; match counts are zero for the current absent process rather than the final thread','Recorded/final findings retain sampled 500 ms while current rule is 60000 ms','Target replacement preserves unsaved edits','Alert controls remain hidden'])
add('QA-038','PASSED','CPU-spin/recovery recordings, direct stepping, Timeline drag preview, keyboard selection, past row, mark and filters agree.', ['fixture-driver-observations.json','two-hour-seed.json'],['Previous/Next selected adjacent real recording times 1793134316/1793134256','Recorded 99% CPU finding names qa-spin/TID42 and sampled 500 ms','Past row timestamp and selected mark agree','Severity and type filters remove both findings and marks','Timeline preview and Home work; Live resumes current data'])
add('QA-039','PASSED','Two hours of exact seeded recordings were checked. Earlier controls/scroll, real collector interruption, retry, bounds, sparse gaps, missing selection, empty installation and help were observed.', ['closing-observations.json','closing-two-hour-seed.json','closing-empty-seed.json'],['Two-hour first/last bounds match the seed','Earlier periods load through controls and scrolling','60 visible finding rows have 60 unique row texts','Loading says Checking an earlier period','Actual collector interruption shows Failed to fetch and Select Load earlier to try again','Restart and retry reach the oldest recording','Home selects the first recording; End returns Live','Sparse gaps are counted explicitly','Missing recording says No recording at this time','Empty installation says No recordings yet and No recordings to check','Timeline/past-assessment help explains recording limits and navigation by pointer and keyboard'])
add('QA-050','PASSED','Viewer A retained its local trends. Empty-storage viewer B started local trends at 20:48:08 UTC, opened an older stored recording and returned Live without changing A.', ['observations.json'],['A records for several minutes','B sees current selected target','B local trend origin equals its opening time','Stored recording predates B','A stays Live while B replays','B returns Live'])
add('QA-057','PASSED','Rate, selected-range count and cumulative total remain distinct. In range is 12/15/115 for 15 min/1 h/6 h. Missing history shows an em dash and Not available.', ['closing-observations.json'],['Headers are Rate (/s), In range, Total','Each column card explains all three values and shared target network-namespace scope','Rate stays 7.00/s and cumulative total stays 1000 while selected-range count changes','Missing history is unavailable rather than zero'])
add('QA-095','PASSED','All requested thread holds used the 21-thread busy target. Pointer/card stability, release, Read/s→Write/s, focus/scroll/sort and custom range passed. Missing-rate behavior used controlled HTTP input after the real pause negative control retained valid old rates.', ['observations.json','final-browser-observations.json','last-native-observations.json'],['5-minute thread map tile holds for 10 s and during card entry','Wait-channel bar holds for 10 s and during card entry','Thread table cell/row holds for 10 s and during card entry','Every panel updates on pointer release','Read/s and Write/s cards use the correct column value','Missing CPU rate says Not available, holds for 10 s and stays fixed in the card','Focused TID stays focused; scroll stays 391 through polling and sort change','Second thread retains custom From 2026-10-27T20:50 / To 2026-10-27T21:00'])
add('QA-096','FAILED','Whole host changes the pressure chart but does not change Summary pressure findings, despite host full pressure 10% and cgroup full pressure 0%. Other resource hold, filter, range/readout, active-counter and process-reset expectations passed.', ['observations.json','controlled-observations.json','closing-observations.json','resources-last-observations.json','native-complete-observations.json','QA-096-confirmed-host-scope-summary.png'],['Pressure table, network row and sockets cell/card freeze for 10 s and refresh after release','Active counters move before inactive counters','Checkbox focus survives polling; clearing it resets scroll from 441 to 0','Idle socket filtering applies at once','1 h/6 h trigger resource reads and refresh charts/range counts','Range and scope changes remove active chart cards immediately','RSS findings stay consistent for the same steady-growth analysis window','Process replacement while socket/map pointers are held clears old rows and cards; new process samples appear'])
add('QA-098','FAILED','An address-space bar has no hover card, and the address map changes during a 10-second pointer hold. One limited retry confirms missing bar hover help. Grid/card, controls, heap margin, process reset and controlled sampler-session reset passed.', ['native-observations.json','native-complete-observations.json','last-native-observations.json','memory-controls-observations.json','QA-098-map-grid-stability-attempt.png','QA-098-bar-no-card-retry.png'],['Address space & zoom and Member regions open','Grid facts/grid/charts/card freeze for 10 s and remain fixed inside the card','Stack and heap clicks select the requested bar','Grid span stays fixed for 4096-byte growth inside the margin and expands for 4 MiB growth beyond it','Escape closes the card; a second Escape has no effect','Member-region scrolling is attempted and stays stable','Actual target replacement removes old addresses/rows/cards and preserves open folds','Controlled sampler session change with the same PID shows waiting, removes old layout/cards/chart points and preserves folds','New layout uses 0x9000–0xb000; memory charts restart at Collecting'],[{'expectation':'Move from an address-space bar into its hover card','disposition':'BLOCKED_BY_CONFIRMED_PRODUCT_FAILURE','reason':'The bar hover card does not appear.'},{'expectation':'Repeat after a literal restart of main sampler PID 74','disposition':'EXCLUDED_BY_USER_CONSTRAINT','reason':'The user permits stop/restart only busy and owned fixtures. The main sampler is preserved, and no extra sampler is authorized. Equivalent frontend new-session reset is verified through controlled HTTP input.'}])
add('QA-121','PASSED','Real collector omits alerts. Settings and #settings remain usable. Controlled alerts:[] followed by omitted alerts never exposes alert controls or sends alert-settings requests.', ['fixture-observations.json','finish-observations.json'],['Real /api/live has no alerts field','No Open alerts or Recent alerts','No alert settings editor or toggle','No /api/alert-settings request','Settings survives direct #settings reload','Controlled empty alerts array followed by omission preserves monitoring/Settings'])
issues=[{'id':'UI-F001','case':'QA-037','first_valid_failure':'fixture-driver-observations.json, hover 3.3 s; limited retry 3.8 s','steps':['Open Settings on a live fixture.','Hover Add rule, Save or Reset to config file for more than three seconds.','Repeat once.'],'expected':'Contextual hover help opens for each control.','actual':'No help card opens. Column/section labels and keyboard wrappers do open help.','evidence':['qa-037-continuation-failure.png','fixture-driver-observations.json']},{'id':'UI-F002','case':'QA-096','first_valid_failure':'closing-observations.json, whole-host-scope-summary','steps':['Use controlled host full pressure 10%, cgroup full pressure 0%, and distinct host/cgroup history.','Select 1 h, then 6 h.','Select Whole host.'],'expected':'Pressure chart/readout and Summary pressure findings follow the selected scope.','actual':'The pressure chart changes to the host history; Summary stays byte-for-byte unchanged and retains cgroup-based findings.','evidence':['QA-096-confirmed-host-scope-summary.png','closing-observations.json']},{'id':'UI-F003','case':'QA-098','first_valid_failure':'native-observations.json, map-grid-stability','steps':['Open Address space & zoom for the growing native fixture.','Hold the pointer on a bar for more than three seconds and then ten seconds.','Repeat once on the heap bar.'],'expected':'The map/bar stays fixed and a fixed card can be entered.','actual':'No bar hover card appears. During the retry the map HTML changes under the pointer (barFrozen=false). Grid card stability is separately verified.','evidence':['QA-098-map-grid-stability-attempt.png','QA-098-bar-no-card-retry.png','native-complete-observations.json']}]
invalid=[{'files':['observations.json'],'reason':'Early help probes waited less than the documented 3000 ms. A pause-rate probe hit an existing overlay. These are invalid harness attempts.'},{'files':['finish-observations.json','finish.log'],'reason':'Several checks did not await Historical/Live or used a recording without layout. Process-name fixtures became ambiguous because exited container children remained zombies. A hidden current-configuration change was wrongly included in a whole-page equality assertion. These checks are invalid; PID-owned fixtures and explicit observation waits replace them.'},{'files':['native-observations.json','native-complete-observations.json'],'reason':'Immediate reads during Process details fold animation returned empty text. Some later native steps were interrupted before their deleted/long-argument fixture started. The valid first bar hover failure remains FAILED.'},{'files':['controlled-observations.json'],'reason':'An unchanged prefix left Save disabled. The initial replacement history was not yet fetched. One text assertion assumed cell whitespace. Scrolling exhausted earlier periods before an outage probe. A broad help locator matched multiple cards. These are invalid setup/assertion attempts; corrected independent checks are in closing-observations.json.'},{'files':['last-native-observations.json','QA-028-deleted-visible-failure.png'],'reason':'The target at this point was a normal process: exe_deleted=false and command_truncated=false. This cannot test deleted/truncated details. The actual sampler pause retained valid CPU rates, so the missing-rate precondition was absent.'},{'files':['final-browser-observations.json','QA-028-valid-deleted-truncated-failure.png'],'reason':'The diagnostic truncatedMarked flag searched for the word truncated. The requirement says marked; visible text ends with an ellipsis and the real API command_truncated flag is true. The diagnostic assertion is invalid; the observed ellipsis satisfies the c16 requirement.'},{'files':['closing.log'],'reason':'The final memory reset probe used an incomplete controlled layout and failed before execution. The full-layout proof is in memory-controls-observations.json.'}]
counts={x:sum(c['status']==x for c in cases) for x in ['PASSED','FAILED','BLOCKED','NOT_RUN']}
assert counts=={'PASSED':9,'FAILED':3,'BLOCKED':0,'NOT_RUN':0}
for c in cases:
 for f in c['evidence']:assert (R/f).exists(),f
now_utc=datetime.datetime.now(datetime.timezone.utc).isoformat()
packages=[p for p in inventory['packages'] if p['platform']=='el9' and p['version']=='dev-c16a553']
output={'schema_version':1,'run_id':'qa-c16a553-ui-final','tier':'Full (assigned 12 cases)','scope':ids,'package_version':'dev-c16a553','source_revision':'c16a55383c4bc6a219c270aa4f7cf9b55c97e45a','case_catalog_revision':'c16a55383c4bc6a219c270aa4f7cf9b55c97e45a','packages':packages,'started_utc':'2026-10-27T20:43:44Z','finished_utc':now_utc,'environment':{'browser':'Chromium 155.0.8059.84 via Playwright','viewports':[[1280,800],[1440,1000]],'main_url':'http://127.0.0.1:19401','independent_collector_url':'http://127.0.0.1:19490','collector_binary_sha256':hashlib.sha256((P/'package/triangulator/bin/triangulator-collector').read_bytes()).hexdigest(),'sampler_binary_sha256':hashlib.sha256((P/'package/triangulator/bin/triangulator-sampler').read_bytes()).hexdigest(),'source_build_used':False,'browser_fallback':'User authorized Chromium after the parent had two T3 snapshot timeouts.','clock':'Real wall clock. No Date.now override.'},'counts':counts,'cases':cases,'issues':issues,'invalid_or_interrupted_attempts':invalid,'remaining_unverified_expectations':[{'case':'QA-098','expectation':'Literal main-sampler restart','disposition':'EXCLUDED_BY_USER_CONSTRAINT','frontend_equivalent':'Verified in memory-controls-observations.json'}],'scripts':[p.name for p in sorted(R.glob('*.mjs'))]+['seed.py','native.py','native-next.py','finalize.py'],'constraints':['No product/repository edits, commits, pull requests, messages, or source build.','Only two owned qa-ui-* targets were added; both were removed.','Existing default PID38, second PID37, periodic PID63627, main collector PID267337, and sampler PID74 were preserved.','The periodic-stop file and existing watch configuration were not changed.','No native confirmation was required by the executed test-owned fixture updates. No auto-dismissed confirmation was used as evidence.'],'cleanup':read('cleanup.json')}
output['ownership_clarification']={'case':'QA-098','historical_label':'EXCLUDED_BY_USER_CONSTRAINT','correct_interpretation':'Parent ownership allocation, not a user prohibition. This child preserved sampler PID 74. The parent will perform the literal restart independently and attach a supplemental observation. QA-098 stays FAILED.','parent_supplement_status':'PARENT_EXECUTING','original_record':'results-before-parent-sampler-supplement.json'}
(R/'results-final.json').write_text(json.dumps(output,indent=2))
compact={'package_version':output['package_version'],'source_revision':output['source_revision'],'counts':counts,'cases':[{k:c[k] for k in ['id','revision','status','observations','evidence','unverified_or_excluded_expectations']}for c in cases],'issues':issues,'excluded_expectations':output['remaining_unverified_expectations'],'cleanup':{'stopped_owned_pids':output['cleanup']['stopped_owned_pids'],'main_container_left_available':True}}
(R/'observations-compact.json').write_text(json.dumps(compact,indent=2))
print(json.dumps({'counts':counts,'cases':{c['id']:c['status']for c in cases},'excluded_expectations':1,'results':str(R/'results-final.json')},indent=2))
